import{_ as p,a0 as a,w as r,s as u,I as i,x as n,a1 as s,A as e,ao as f}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"使用“最近通知工具”保持桌面通知歷史 | LCTT x X-CMD","titleTemplate":false,"description":"使用“最近通知工具”保持桌面通知歷史 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用“最近通知工具”保持桌面通知歷史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用“最近通知工具”保持桌面通知歷史 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150123 Keep History Of Notifications With Recent Notifications AppIndicator","title":"使用“最近通知工具”保持桌面通知歷史","tag":"201503","desc":""},"relativePath":"201503/20150123 Keep History Of Notifications With Recent Notifications AppIndicator.md","filePath":"[post].md"}'),d={name:"201503/20150123 Keep History Of Notifications With Recent Notifications AppIndicator.md"};function l(m,t,T,b,g,C){const o=a("Link");return r(),u("div",null,[t[16]||(t[16]=i("h1",{id:"使用-最近通知工具-保持桌面通知歷史",tabindex:"-1"},[n("使用“最近通知工具”保持桌面通知歷史 "),i("a",{class:"header-anchor",href:"#使用-最近通知工具-保持桌面通知歷史","aria-label":"Permalink to “使用“最近通知工具”保持桌面通知歷史”"},"​")],-1)),t[17]||(t[17]=i("p",null,[i("img",{src:"http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/01/recent_notifications_Ubuntu_14.jpeg",alt:"How to see recent notifications in Ubuntu 14.04"})],-1)),i("p",null,[t[1]||(t[1]=n("大多數桌面環境像Unity和Gnome都有通知特性。我很喜歡其中一些。它尤其當我",-1)),s(o,{href:"http://itsfoss.com/apps-internet-streaming-radio-ubuntu/"},{default:e(()=>[...t[0]||(t[0]=[n("在Ubuntu上收聽流媒體",-1)])]),_:1}),t[2]||(t[2]=n("時幫到我。默認上通知會在桌面的頂部顯示幾秒接着就會消失。如果你聽見了通知的聲音但是沒有看到內容怎麼辦？你該如何知道通知的內容？",-1))]),t[18]||(t[18]=f(`<p>如果你可以看到最近所有通知的歷史會很棒吧？是的，我知道這很棒。你可以在Ubuntu Unity或者Gnome中使用最近<strong>通知小工具</strong>來追蹤所有的最近通知。</p><p>最近通知位於頂部面板，並且記錄了最近所有通知的歷史。當它捕獲到新的通知後，它就會變綠來表明你有未讀的通知。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/01/recent_notifications_Ubuntu.jpeg" alt="Recent notifications in Ubuntu 14.04"></p><p>當你點擊它後，你就會看到最近所有的通知。你可以選擇清空所有或者刪除部分。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/01/recent_notifications_Ubuntu_1.jpeg" alt="Recent notifications applet indicator"></p><p>不幸的是它沒有配置選項。因此你不能屏蔽特定程序的通知。所有的通知都會被保存。</p><h3 id="在ubuntu-14-04-和-14-10-中安裝最近通知工具" tabindex="-1">在Ubuntu 14.04 和 14.10 中安裝最近通知工具 <a class="header-anchor" href="#在ubuntu-14-04-和-14-10-中安裝最近通知工具" aria-label="Permalink to “在Ubuntu 14.04 和 14.10 中安裝最近通知工具”">​</a></h3><p>一般説來這個最近通知工具應該也可以在Linux Mint Cinnamon版本中運行。你可以試一試。使用下面的命令來在在Ubuntu 14.04 和 14.10 中安裝最近通知工具：</p><pre><code>sudo add-apt-repository ppa:jconti/recent-notifications
sudo apt-get update
sudo apt-get install indicator-notifications
</code></pre><p>安裝完成後，重新登錄後你就可以用了。現在媽媽再也不用擔心我的通知沒看到了。很方便的小工具，不是麼？</p><hr>`,11)),i("p",null,[t[4]||(t[4]=n("via: ",-1)),s(o,{href:"http://itsfoss.com/notifications-appindicator/"},{default:e(()=>[...t[3]||(t[3]=[n("http://itsfoss.com/notifications-appindicator/",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=n("作者：",-1)),s(o,{href:"http://itsfoss.com/author/Abhishek/"},{default:e(()=>[...t[5]||(t[5]=[n("Abhishek",-1)])]),_:1}),t[9]||(t[9]=n(" 譯者：",-1)),s(o,{href:"https://github.com/geekpi"},{default:e(()=>[...t[6]||(t[6]=[n("geekpi",-1)])]),_:1}),t[10]||(t[10]=n(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[7]||(t[7]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[13]||(t[13]=n("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[11]||(t[11]=[n("LCTT",-1)])]),_:1}),t[14]||(t[14]=n(" 原創翻譯，",-1)),s(o,{href:"http://linux.cn/"},{default:e(()=>[...t[12]||(t[12]=[n("Linux中國",-1)])]),_:1}),t[15]||(t[15]=n(" 榮譽推出",-1))])])}const U=p(d,[["render",l]]);export{N as __pageData,U as default};
